"use client"
import type { CSSProperties } from "react"
import { ArrowDown, ArrowUp } from "lucide-react"
import { Alert } from "@atlas/ui-web/compositions/Alert/Alert"
import { Badge } from "@atlas/ui-web/primitives/Badge/Badge"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { Card, CardContent, CardHeader, CardTitle } from "@atlas/ui-web/compositions/Card/Card"
import {
  Chart,
  ChartBar,
  ChartContent,
  ChartDescription,
  ChartHeader,
  ChartTitle,
} from "@atlas/ui-web/compositions/Chart/Chart"
import {
  ListItem,
  ListItemActions,
  ListItemContent,
  ListItemDescription,
  ListItemTitle,
} from "@atlas/ui-web/compositions/ListItem/ListItem"
import { Skeleton } from "@atlas/ui-web/primitives/Skeleton/Skeleton"
import { GREETING, SPENDING_7_DAYS, SUMMARIES, TRANSACTIONS, type Summary } from "../data"
import type { DashboardStatus } from "../schema"

const column: CSSProperties = {
  display: "flex",
  flexDirection: "column",
  gap: "var(--atlas-spacing-4)",
  paddingInline: "var(--atlas-spacing-4)",
  paddingBlockEnd: "var(--atlas-spacing-6)",
}

const text = (size: string, weight: string, color: string): CSSProperties => ({
  margin: 0,
  fontSize: size,
  fontWeight: weight,
  color,
  lineHeight: "var(--atlas-line-height-snug)",
})

function Header() {
  return (
    <header style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-1)", paddingBlockStart: "var(--atlas-spacing-4)" }}>
      <h1 style={text("var(--atlas-text-h1)", "var(--atlas-font-weight-bold)", "var(--atlas-foreground)")}>Dashboard</h1>
      <p style={text("var(--atlas-text-body)", "var(--atlas-font-weight-regular)", "var(--atlas-foreground-muted)")}>{GREETING}</p>
    </header>
  )
}

function ChangeBadge({ change, upIsGood }: Pick<Summary, "change" | "upIsGood">) {
  const up = change > 0
  const good = up === upIsGood
  const Icon = up ? ArrowUp : ArrowDown
  return (
    <Badge
      variant={good ? "success" : "danger"}
      size="sm"
      leadingIcon={<Icon size={12} aria-hidden="true" />}
    >
      <span className="sr-only">{up ? "Up " : "Down "}</span>
      {Math.abs(change)}%
    </Badge>
  )
}

function SummaryGrid({ loading }: { loading: boolean }) {
  return (
    <section
      aria-label="Summary"
      aria-busy={loading}
      style={{ display: "grid", gridTemplateColumns: "repeat(2, minmax(0, 1fr))", gap: "var(--atlas-spacing-3)" }}
    >
      {SUMMARIES.map((s) => (
        <Card key={s.label} variant="outlined" size="sm">
          <CardContent>
            <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-2)" }}>
              <p style={text("var(--atlas-text-body-sm)", "var(--atlas-font-weight-medium)", "var(--atlas-foreground-muted)")}>{s.label}</p>
              {loading ? (
                <>
                  <Skeleton style={{ height: "var(--atlas-spacing-6)" }} />
                  <Skeleton style={{ height: "var(--atlas-spacing-4)", inlineSize: "60%" }} />
                </>
              ) : (
                <>
                  <p style={text("var(--atlas-text-h2)", "var(--atlas-font-weight-semibold)", "var(--atlas-foreground)")}>{s.value}</p>
                  <div style={{ display: "flex", alignItems: "center", gap: "var(--atlas-spacing-1_5)" }}>
                    <ChangeBadge change={s.change} upIsGood={s.upIsGood} />
                    <span style={text("var(--atlas-text-caption)", "var(--atlas-font-weight-regular)", "var(--atlas-foreground-subtle)")}>vs last month</span>
                  </div>
                </>
              )}
            </div>
          </CardContent>
        </Card>
      ))}
    </section>
  )
}

function SpendingChart({ loading }: { loading: boolean }) {
  return (
    <Chart state={loading ? "loading" : "default"}>
      <ChartHeader>
        <ChartTitle>Spending</ChartTitle>
        <ChartDescription>Daily spending over the last 7 days</ChartDescription>
      </ChartHeader>
      <ChartContent loadingLabel="Loading spending chart">
        <ChartBar
          aria-label="Bar chart of daily spending for the last 7 days, in dollars"
          data={SPENDING_7_DAYS}
          xKey="day"
          dataKey="spent"
          label="Spent"
        />
      </ChartContent>
    </Chart>
  )
}

function RecentActivity({ loading }: { loading: boolean }) {
  return (
    <Card variant="outlined" size="md">
      <CardHeader>
        <CardTitle as="h2">Recent activity</CardTitle>
      </CardHeader>
      <CardContent>
        <ul aria-busy={loading} style={{ listStyle: "none", margin: 0, padding: 0, display: "flex", flexDirection: "column" }}>
          {loading
            ? TRANSACTIONS.map((t) => (
                <li key={t.id} style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-2)", paddingBlock: "var(--atlas-spacing-3)" }}>
                  <Skeleton style={{ height: "var(--atlas-spacing-4)", inlineSize: "50%" }} />
                  <Skeleton style={{ height: "var(--atlas-spacing-3)", inlineSize: "35%" }} />
                </li>
              ))
            : TRANSACTIONS.map((t) => (
                <ListItem key={t.id} as="li" size="md">
                  <ListItemContent>
                    <ListItemTitle>{t.name}</ListItemTitle>
                    <ListItemDescription>
                      {t.category} · {t.date}
                    </ListItemDescription>
                  </ListItemContent>
                  <ListItemActions>
                    <span
                      style={text(
                        "var(--atlas-text-body)",
                        "var(--atlas-font-weight-semibold)",
                        t.income ? "var(--atlas-success)" : "var(--atlas-foreground)",
                      )}
                    >
                      {t.amount}
                    </span>
                  </ListItemActions>
                </ListItem>
              ))}
        </ul>
      </CardContent>
    </Card>
  )
}

export function Dashboard({ status, onRetry }: { status: DashboardStatus; onRetry: () => void }) {
  if (status === "error") {
    return (
      <div style={column}>
        <Header />
        <Alert
          variant="danger"
          title="Couldn't load your dashboard"
          description="Check your connection and try again."
          actions={
            <Button variant="outline" size="sm" onClick={onRetry}>
              Retry
            </Button>
          }
        />
      </div>
    )
  }
  const loading = status === "loading"
  return (
    <div style={column}>
      <Header />
      <SummaryGrid loading={loading} />
      <SpendingChart loading={loading} />
      <RecentActivity loading={loading} />
    </div>
  )
}

