"use client"
import { useEffect, useState } from "react"
import { TabsList, TabsRoot, TabsTrigger } from "@atlas/ui-web/patterns/Tabs/Tabs"
import { FlowShell } from "../_shared/FlowShell"
import { DASHBOARD_STATUSES, type DashboardStatus } from "./schema"
import { Dashboard } from "./steps/Dashboard"

const RETRY_DELAY_MS = 900

export default function DashboardSummaryPage() {
  const [status, setStatus] = useState<DashboardStatus>("loaded")
  // A retry shows the loading state, then resolves to loaded.
  const [retrying, setRetrying] = useState(false)

  useEffect(() => {
    if (!retrying) return
    const id = setTimeout(() => {
      setStatus("loaded")
      setRetrying(false)
    }, RETRY_DELAY_MS)
    return () => clearTimeout(id)
  }, [retrying])

  const select = (value: string) => {
    setRetrying(false)
    setStatus(value as DashboardStatus)
  }
  const retry = () => {
    setStatus("loading")
    setRetrying(true)
  }

  return (
    <FlowShell
      title="Dashboard summary"
      step={0}
      totalSteps={1}
      showProgress={false}
      onReset={() => select("loaded")}
      phoneBackground="var(--atlas-background)"
    >
      <div style={{ paddingInline: "var(--atlas-spacing-4)", paddingBlockStart: "var(--atlas-spacing-2)" }}>
        <TabsRoot variant="segmented" size="sm" value={status} onValueChange={select}>
          <TabsList aria-label="Preview state">
            {DASHBOARD_STATUSES.map((s) => (
              <TabsTrigger key={s.value} value={s.value}>
                {s.label}
              </TabsTrigger>
            ))}
          </TabsList>
        </TabsRoot>
      </div>
      <Dashboard status={status} onRetry={retry} />
    </FlowShell>
  )
}

